-- STILLFORM · one-file database setup
--
-- Generated by scripts/build-seed.mjs. Paste into the Supabase SQL editor of a
-- new project and run it once. Every statement is safe to run again.
-- Contains: 20261028120000_core_schema.sql, 20261028120100_security.sql, 20261028120200_storage.sql, 20261028120300_storefront_api.sql, 20261028120400_admin_api.sql, 20261028120500_api_grants.sql, 20261029120000_checkout_protection.sql, seed.sql

-- ===== 20261028120000_core_schema.sql =====

-- STILLFORM · core schema
--
-- Catalogue, editorial content, store settings and orders. Every statement is
-- safe to run again on a database that already has it, so the bundled
-- supabase/setup.sql can be re-run without harm.

-- ---------------------------------------------------------------------------
-- Shared helpers

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Media library: every image the store shows, wherever it is hosted.

create table if not exists public.media (
  id text primary key,
  -- Absolute URL (Supabase Storage) or a path served by the site itself (/media/...).
  src text not null check (char_length(src) between 1 and 2048),
  -- Object path in the "media" bucket when the file was uploaded from the dashboard.
  storage_path text,
  alt text not null default '' check (char_length(alt) <= 500),
  width integer not null check (width > 0),
  height integer not null check (height > 0),
  origin text not null default 'uploaded' check (origin in ('supplied', 'supplied-retouched', 'generated', 'uploaded')),
  replace_note text,
  -- Smaller copies for srcset: [{ "width": 640, "src": "..." }, …], widest last.
  variants jsonb not null default '[]'::jsonb check (jsonb_typeof(variants) = 'array'),
  -- CSS object-position for cropped display, e.g. "30% 50%".
  focus text check (focus is null or focus ~ '^\d{1,3}% \d{1,3}%$'),
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Catalogue

create table if not exists public.categories (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  label text not null check (char_length(label) between 1 and 60),
  position integer not null default 0
);

create table if not exists public.products (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(id) <= 80),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80),
  name text not null check (char_length(name) between 1 and 120),
  category_id text not null references public.categories (id),
  status text not null default 'draft' check (status in ('draft', 'active', 'archived')),
  -- Minor units (cents) of the store currency.
  price integer not null check (price between 0 and 100000000),
  summary text not null default '' check (char_length(summary) <= 300),
  description text not null default '' check (char_length(description) <= 4000),
  details text[] not null default '{}',
  composition text not null default '' check (char_length(composition) <= 300),
  care text[] not null default '{}',
  fit text not null default '' check (char_length(fit) <= 600),
  fabric text check (char_length(fabric) <= 1200),
  sizes text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists products_status_idx on public.products (status);

create table if not exists public.colorways (
  product_id text not null references public.products (id) on delete cascade,
  id text not null check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(id) <= 60),
  name text not null check (char_length(name) between 1 and 60),
  swatch text not null default '#cccccc' check (swatch ~ '^#[0-9a-fA-F]{6}$'),
  position integer not null default 0,
  primary key (product_id, id)
);

-- Which image plays which part for a colourway. Front, back and side are single
-- images on the shared rail canvas; the other roles are ordered lists.
create table if not exists public.colorway_media (
  product_id text not null,
  colorway_id text not null,
  role text not null check (role in ('front', 'back', 'side', 'gallery', 'lifestyle', 'detail')),
  position integer not null default 0 check (position >= 0),
  media_id text not null references public.media (id) on delete restrict,
  primary key (product_id, colorway_id, role, position),
  foreign key (product_id, colorway_id) references public.colorways (product_id, id) on delete cascade,
  check (role not in ('front', 'back', 'side') or position = 0)
);
create index if not exists colorway_media_media_idx on public.colorway_media (media_id);

create table if not exists public.variants (
  sku text primary key check (char_length(sku) between 1 and 120),
  product_id text not null,
  colorway_id text not null,
  size text not null check (char_length(size) between 1 and 24),
  stock integer not null default 0 check (stock >= 0),
  unique (product_id, colorway_id, size),
  foreign key (product_id, colorway_id) references public.colorways (product_id, id) on delete cascade
);
create index if not exists variants_low_stock_idx on public.variants (stock);

create table if not exists public.collections (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (char_length(title) between 1 and 120),
  season text not null default '' check (char_length(season) <= 120),
  summary text not null default '' check (char_length(summary) <= 1200),
  position integer not null default 0,
  published boolean not null default true
);

create table if not exists public.collection_products (
  collection_id text not null references public.collections (id) on delete cascade,
  product_id text not null references public.products (id) on delete cascade,
  position integer not null default 0,
  primary key (collection_id, product_id)
);

-- The interactive rail: one hanger per product colourway, in display order.
create table if not exists public.rail_placements (
  product_id text not null,
  colorway_id text not null,
  position integer not null,
  primary key (product_id, colorway_id),
  foreign key (product_id, colorway_id) references public.colorways (product_id, id) on delete cascade
);

-- Products featured in the homepage collection grid; the first is shown largest.
create table if not exists public.featured_products (
  product_id text primary key references public.products (id) on delete cascade,
  position integer not null default 0
);

-- "Wear it with". Directional and ordered, so a future "complete the look"
-- feature can build on it without changing the relationship.
create table if not exists public.product_pairings (
  product_id text not null references public.products (id) on delete cascade,
  paired_product_id text not null references public.products (id) on delete cascade,
  position integer not null default 0,
  primary key (product_id, paired_product_id),
  check (product_id <> paired_product_id)
);

-- ---------------------------------------------------------------------------
-- Editorial: the lookbook is a sequence of spreads in curated layouts.

create table if not exists public.lookbooks (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (char_length(title) between 1 and 120),
  season text not null default '' check (char_length(season) <= 120),
  summary text not null default '' check (char_length(summary) <= 600),
  published boolean not null default true
);

create table if not exists public.lookbook_spreads (
  id text primary key check (char_length(id) between 1 and 80),
  lookbook_id text not null references public.lookbooks (id) on delete cascade,
  layout text not null check (layout in ('cinematic', 'pair', 'pair-flip', 'wide', 'materials')),
  note text check (char_length(note) <= 600),
  position integer not null default 0,
  published boolean not null default true
);

create table if not exists public.looks (
  id text primary key check (char_length(id) between 1 and 80),
  spread_id text not null references public.lookbook_spreads (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 120),
  caption text not null default '' check (char_length(caption) <= 300),
  tone text not null default 'plaster' check (tone in ('plaster', 'bone', 'graphite', 'ink')),
  kind text not null default 'campaign' check (kind in ('campaign', 'detail')),
  media_id text references public.media (id) on delete set null,
  position integer not null default 0,
  published boolean not null default true
);
create index if not exists looks_media_idx on public.looks (media_id);

create table if not exists public.look_pieces (
  look_id text not null references public.looks (id) on delete cascade,
  position integer not null default 0,
  product_id text not null,
  colorway_id text not null,
  view text not null default 'front' check (view in ('front', 'back', 'side')),
  primary key (look_id, position),
  foreign key (product_id, colorway_id) references public.colorways (product_id, id) on delete cascade
);

-- ---------------------------------------------------------------------------
-- Settings. Public settings are readable by every visitor; private settings
-- are for administrators only. Each table holds exactly one row.

create table if not exists public.store_settings (
  id boolean primary key default true check (id),
  name text not null default 'STILLFORM' check (char_length(name) between 1 and 60),
  description text not null default '' check (char_length(description) <= 600),
  currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  locale text not null default 'en-US' check (locale ~ '^[a-z]{2,3}(-[A-Z]{2})?$'),
  low_stock_threshold integer not null default 3 check (low_stock_threshold between 0 and 100),
  order_prefix text not null default 'SF' check (order_prefix ~ '^[A-Z]{1,6}$'),
  contact jsonb not null default '{}'::jsonb,
  rail jsonb not null default '{}'::jsonb,
  home jsonb not null default '{}'::jsonb,
  footer jsonb not null default '{}'::jsonb,
  -- { "enabled": false, "methods": [{ "id", "label", "instructions", "enabled" }] }
  checkout jsonb not null default '{"enabled": false, "methods": []}'::jsonb,
  -- { "flatRate": 0, "freeOver": null, "note": "" } in minor units
  shipping jsonb not null default '{"flatRate": 0, "freeOver": null, "note": ""}'::jsonb,
  policies jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.store_private_settings (
  id boolean primary key default true check (id),
  order_notification_email text check (order_notification_email is null or order_notification_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  notes text check (char_length(notes) <= 4000),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Orders. Created only through public.place_order(); changed only through
-- public.admin_update_order(). Items keep a snapshot of what was bought.

create sequence if not exists public.order_number_seq start 1001;

create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  status text not null default 'pending' check (status in ('pending', 'confirmed', 'shipped', 'delivered', 'cancelled')),
  payment_status text not null default 'unpaid' check (payment_status in ('unpaid', 'paid', 'refunded')),
  payment_method text not null,
  payment_method_label text not null,
  payment_instructions text not null default '',
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  subtotal integer not null check (subtotal >= 0),
  shipping integer not null check (shipping >= 0),
  total integer not null check (total >= 0),
  email text not null,
  name text not null,
  phone text not null default '',
  address jsonb not null,
  notes text not null default '',
  restocked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  confirmed_at timestamptz,
  shipped_at timestamptz,
  delivered_at timestamptz,
  cancelled_at timestamptz,
  paid_at timestamptz,
  check (total = subtotal + shipping)
);
create index if not exists orders_created_idx on public.orders (created_at desc);
create index if not exists orders_status_idx on public.orders (status);

create table if not exists public.order_items (
  id bigint generated always as identity primary key,
  order_id uuid not null references public.orders (id) on delete cascade,
  position integer not null,
  sku text not null,
  product_id text not null,
  colorway_id text not null,
  product_name text not null,
  colorway_name text not null,
  size text not null,
  unit_price integer not null check (unit_price >= 0),
  quantity integer not null check (quantity > 0),
  line_total integer not null check (line_total = unit_price * quantity),
  image_src text
);
create index if not exists order_items_order_idx on public.order_items (order_id);

create table if not exists public.order_events (
  id bigint generated always as identity primary key,
  order_id uuid not null references public.orders (id) on delete cascade,
  kind text not null check (kind in ('placed', 'status', 'payment', 'note')),
  from_value text,
  to_value text,
  note text,
  actor uuid,
  created_at timestamptz not null default now()
);
create index if not exists order_events_order_idx on public.order_events (order_id, created_at);

-- ---------------------------------------------------------------------------
-- Order lifecycle rules, enforced on every update path.
--
--   pending → confirmed → shipped → delivered
--   pending | confirmed → cancelled            (stock is returned once)
--   unpaid → paid → refunded

create or replace function public.orders_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.reference <> old.reference or new.subtotal <> old.subtotal or new.shipping <> old.shipping
     or new.total <> old.total or new.currency <> old.currency or new.created_at <> old.created_at then
    raise exception 'order_is_immutable' using hint = 'Totals, currency and reference cannot change after an order is placed.';
  end if;

  if new.status <> old.status then
    if not (
      (old.status = 'pending' and new.status in ('confirmed', 'cancelled')) or
      (old.status = 'confirmed' and new.status in ('shipped', 'cancelled')) or
      (old.status = 'shipped' and new.status = 'delivered')
    ) then
      raise exception 'invalid_status_transition' using detail = old.status || ' -> ' || new.status;
    end if;
    case new.status
      when 'confirmed' then new.confirmed_at := now();
      when 'shipped' then new.shipped_at := now();
      when 'delivered' then new.delivered_at := now();
      when 'cancelled' then new.cancelled_at := now();
      else null;
    end case;
    -- Cancelled is terminal, so this runs at most once per order.
    if new.status = 'cancelled' and old.restocked_at is null then
      update public.variants v
         set stock = v.stock + i.quantity
        from (select sku, sum(quantity)::integer as quantity from public.order_items where order_id = new.id group by sku) i
       where v.sku = i.sku;
      new.restocked_at := now();
    end if;
  end if;

  if new.payment_status <> old.payment_status then
    if not (
      (old.payment_status = 'unpaid' and new.payment_status = 'paid') or
      (old.payment_status = 'paid' and new.payment_status = 'refunded')
    ) then
      raise exception 'invalid_payment_transition' using detail = old.payment_status || ' -> ' || new.payment_status;
    end if;
    if new.payment_status = 'paid' then
      new.paid_at := now();
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists orders_guard on public.orders;
create trigger orders_guard before update on public.orders
  for each row execute function public.orders_guard();

drop trigger if exists products_touch on public.products;
create trigger products_touch before update on public.products
  for each row execute function public.touch_updated_at();

drop trigger if exists store_settings_touch on public.store_settings;
create trigger store_settings_touch before update on public.store_settings
  for each row execute function public.touch_updated_at();

drop trigger if exists store_private_settings_touch on public.store_private_settings;
create trigger store_private_settings_touch before update on public.store_private_settings
  for each row execute function public.touch_updated_at();

insert into public.store_settings (id) values (true) on conflict (id) do nothing;
insert into public.store_private_settings (id) values (true) on conflict (id) do nothing;


-- ===== 20261028120100_security.sql =====

-- STILLFORM · access control
--
-- Administrators are listed in public.admins, which only a database owner can
-- change (SQL editor or service role); there is no way to grant admin from the
-- browser. Every table has row level security. Visitors can read published
-- storefront content only; orders, customer details and private settings are
-- readable by administrators only, and are never written directly by clients:
-- orders go through public.place_order(), admin changes through admin_* functions.

create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  note text,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.admins where user_id = auth.uid());
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- True when a media row is used by something a visitor can see.
create or replace function public.media_is_public(p_media_id text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.colorway_media cm
      join public.products p on p.id = cm.product_id
     where cm.media_id = p_media_id and p.status = 'active'
  ) or exists (
    select 1 from public.looks l
      join public.lookbook_spreads s on s.id = l.spread_id
      join public.lookbooks b on b.id = s.lookbook_id
     where l.media_id = p_media_id and l.published and s.published and b.published
  ) or exists (
    select 1 from public.store_settings st where st.home #>> '{statement,mediaId}' = p_media_id
  );
$$;

revoke all on function public.media_is_public(text) from public;
grant execute on function public.media_is_public(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Row level security

alter table public.media enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.colorways enable row level security;
alter table public.colorway_media enable row level security;
alter table public.variants enable row level security;
alter table public.collections enable row level security;
alter table public.collection_products enable row level security;
alter table public.rail_placements enable row level security;
alter table public.featured_products enable row level security;
alter table public.product_pairings enable row level security;
alter table public.lookbooks enable row level security;
alter table public.lookbook_spreads enable row level security;
alter table public.looks enable row level security;
alter table public.look_pieces enable row level security;
alter table public.store_settings enable row level security;
alter table public.store_private_settings enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.order_events enable row level security;
alter table public.admins enable row level security;

-- Administrators manage the whole catalogue and editorial content.
do $$
declare
  t text;
begin
  foreach t in array array[
    'media', 'categories', 'products', 'colorways', 'colorway_media', 'variants', 'collections',
    'collection_products', 'rail_placements', 'featured_products', 'product_pairings', 'lookbooks',
    'lookbook_spreads', 'looks', 'look_pieces'
  ] loop
    execute format('drop policy if exists %I on public.%I', t || '_admin_all', t);
    execute format(
      'create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',
      t || '_admin_all', t
    );
  end loop;
end;
$$;

-- Visitors read only what is published.
drop policy if exists categories_public_read on public.categories;
create policy categories_public_read on public.categories for select to anon, authenticated using (true);

drop policy if exists products_public_read on public.products;
create policy products_public_read on public.products for select to anon, authenticated
  using (status = 'active');

drop policy if exists colorways_public_read on public.colorways;
create policy colorways_public_read on public.colorways for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

drop policy if exists colorway_media_public_read on public.colorway_media;
create policy colorway_media_public_read on public.colorway_media for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

drop policy if exists variants_public_read on public.variants;
create policy variants_public_read on public.variants for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

drop policy if exists media_public_read on public.media;
create policy media_public_read on public.media for select to anon, authenticated
  using (public.media_is_public(id));

drop policy if exists collections_public_read on public.collections;
create policy collections_public_read on public.collections for select to anon, authenticated
  using (published);

drop policy if exists collection_products_public_read on public.collection_products;
create policy collection_products_public_read on public.collection_products for select to anon, authenticated
  using (
    exists (select 1 from public.collections c where c.id = collection_id and c.published)
    and exists (select 1 from public.products p where p.id = product_id and p.status = 'active')
  );

drop policy if exists rail_placements_public_read on public.rail_placements;
create policy rail_placements_public_read on public.rail_placements for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

drop policy if exists featured_products_public_read on public.featured_products;
create policy featured_products_public_read on public.featured_products for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

drop policy if exists product_pairings_public_read on public.product_pairings;
create policy product_pairings_public_read on public.product_pairings for select to anon, authenticated
  using (
    exists (select 1 from public.products p where p.id = product_id and p.status = 'active')
    and exists (select 1 from public.products p where p.id = paired_product_id and p.status = 'active')
  );

drop policy if exists lookbooks_public_read on public.lookbooks;
create policy lookbooks_public_read on public.lookbooks for select to anon, authenticated
  using (published);

drop policy if exists lookbook_spreads_public_read on public.lookbook_spreads;
create policy lookbook_spreads_public_read on public.lookbook_spreads for select to anon, authenticated
  using (published and exists (select 1 from public.lookbooks b where b.id = lookbook_id and b.published));

drop policy if exists looks_public_read on public.looks;
create policy looks_public_read on public.looks for select to anon, authenticated
  using (
    published and exists (
      select 1 from public.lookbook_spreads s join public.lookbooks b on b.id = s.lookbook_id
       where s.id = spread_id and s.published and b.published
    )
  );

drop policy if exists look_pieces_public_read on public.look_pieces;
create policy look_pieces_public_read on public.look_pieces for select to anon, authenticated
  using (
    exists (select 1 from public.products p where p.id = product_id and p.status = 'active')
    and exists (select 1 from public.looks l where l.id = look_id and l.published)
  );

-- Public settings: readable by everyone, editable by administrators.
drop policy if exists store_settings_public_read on public.store_settings;
create policy store_settings_public_read on public.store_settings for select to anon, authenticated using (true);
drop policy if exists store_settings_admin_update on public.store_settings;
create policy store_settings_admin_update on public.store_settings for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Private settings: administrators only.
drop policy if exists store_private_settings_admin_read on public.store_private_settings;
create policy store_private_settings_admin_read on public.store_private_settings for select to authenticated
  using (public.is_admin());
drop policy if exists store_private_settings_admin_update on public.store_private_settings;
create policy store_private_settings_admin_update on public.store_private_settings for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Orders: administrators read; nobody writes directly.
drop policy if exists orders_admin_read on public.orders;
create policy orders_admin_read on public.orders for select to authenticated using (public.is_admin());
drop policy if exists order_items_admin_read on public.order_items;
create policy order_items_admin_read on public.order_items for select to authenticated using (public.is_admin());
drop policy if exists order_events_admin_read on public.order_events;
create policy order_events_admin_read on public.order_events for select to authenticated using (public.is_admin());

-- A signed-in user can see whether they themselves are an administrator.
drop policy if exists admins_self_read on public.admins;
create policy admins_self_read on public.admins for select to authenticated using (user_id = auth.uid());

-- Belt and braces: remove direct write privileges where no client should write.
revoke insert, update, delete, truncate on public.orders, public.order_items, public.order_events, public.admins from anon, authenticated;
revoke all on public.store_private_settings from anon;
revoke insert, delete, truncate on public.store_settings, public.store_private_settings from anon, authenticated;
revoke usage on sequence public.order_number_seq from anon, authenticated;


-- ===== 20261028120200_storage.sql =====

-- STILLFORM · image storage
--
-- One public bucket, "media", for product and editorial photographs. Files are
-- readable by URL (so the storefront and CDN can serve them) but only
-- administrators can list, upload, replace or delete them. Uploads are limited
-- to web image formats and 10 MB. The dashboard names every upload with a
-- random id, so unpublished photographs are not guessable.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media', 'media', true, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/avif'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "media: admins read" on storage.objects;
create policy "media: admins read" on storage.objects for select to authenticated
  using (bucket_id = 'media' and public.is_admin());

drop policy if exists "media: admins upload" on storage.objects;
create policy "media: admins upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and public.is_admin());

drop policy if exists "media: admins replace" on storage.objects;
create policy "media: admins replace" on storage.objects for update to authenticated
  using (bucket_id = 'media' and public.is_admin())
  with check (bucket_id = 'media' and public.is_admin());

drop policy if exists "media: admins delete" on storage.objects;
create policy "media: admins delete" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and public.is_admin());


-- ===== 20261028120300_storefront_api.sql =====

-- STILLFORM · storefront API
--
-- storefront_catalog(): the whole published catalogue as one JSON document in
--   the shape of the app's Catalog type (src/catalog/types.ts).
-- place_order(): the only way to create an order. Validates the request,
--   prices it from the database, locks and decrements stock atomically and
--   stores a snapshot of every item. Nothing the browser sends about prices,
--   totals or stock is trusted.

create or replace function public.media_json(m public.media)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', m.id, 'src', m.src, 'alt', m.alt, 'width', m.width, 'height', m.height,
    'origin', m.origin, 'replaceNote', m.replace_note, 'focus', m.focus, 'storagePath', m.storage_path,
    'variants', case when jsonb_array_length(m.variants) > 0 then m.variants end
  ));
$$;

-- Builds the catalogue. With p_admin = false only published content is
-- included, whoever is asking, so an administrator browsing the shop sees
-- exactly what customers see. p_admin = true has no effect unless the caller
-- is an administrator.
create or replace function public.catalog_json(p_admin boolean)
returns jsonb
language sql
stable
set search_path = ''
as $$
  with
  -- Dashboard fields and drafts only ever go to an administrator.
  flags as (select p_admin and public.is_admin() as admin),
  visible_products as (
    select p.* from public.products p where (select admin from flags) or p.status = 'active'
  ),
  product_docs as (
    select p.id, p.name, jsonb_strip_nulls(jsonb_build_object(
      'id', p.id, 'slug', p.slug, 'name', p.name, 'category', p.category_id, 'status', p.status,
      'price', p.price, 'summary', p.summary, 'description', p.description,
      'details', to_jsonb(p.details), 'composition', p.composition, 'care', to_jsonb(p.care),
      'fit', p.fit, 'fabric', p.fabric, 'sizes', to_jsonb(p.sizes),
      'colorways', coalesce((
        select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
          'id', c.id, 'name', c.name, 'swatch', c.swatch,
          'onRail', case when (select admin from flags) then exists (select 1 from public.rail_placements r where r.product_id = c.product_id and r.colorway_id = c.id) end,
          'media', jsonb_strip_nulls(jsonb_build_object(
            'front', (select cm.media_id from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'front'),
            'back', (select cm.media_id from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'back'),
            'side', (select cm.media_id from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'side'),
            'gallery', coalesce((select jsonb_agg(cm.media_id order by cm.position) from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'gallery'), '[]'::jsonb),
            'lifestyle', coalesce((select jsonb_agg(cm.media_id order by cm.position) from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'lifestyle'), '[]'::jsonb),
            'details', coalesce((select jsonb_agg(cm.media_id order by cm.position) from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'detail'), '[]'::jsonb)
          ))
        )) order by c.position, c.id)
        from public.colorways c where c.product_id = p.id
      ), '[]'::jsonb),
      'variants', coalesce((
        select jsonb_agg(jsonb_build_object('sku', v.sku, 'colorwayId', v.colorway_id, 'size', v.size, 'stock', v.stock)
                         order by c.position, array_position(p.sizes, v.size))
        from public.variants v join public.colorways c on c.product_id = v.product_id and c.id = v.colorway_id
        where v.product_id = p.id
      ), '[]'::jsonb),
      'pairsWith', coalesce((
        select jsonb_agg(pp.paired_product_id order by pp.position)
        from public.product_pairings pp join public.products q on q.id = pp.paired_product_id
        where pp.product_id = p.id and ((select admin from flags) or q.status = 'active')
      ), '[]'::jsonb),
      'featured', case when (select admin from flags) then exists (select 1 from public.featured_products f where f.product_id = p.id) end,
      'collectionIds', case when (select admin from flags) then coalesce((select jsonb_agg(cp.collection_id) from public.collection_products cp where cp.product_id = p.id), '[]'::jsonb) end,
      'updatedAt', case when (select admin from flags) then to_jsonb(p.updated_at) end
    )) as doc
    from visible_products p
  ),
  settings as (select * from public.store_settings where id)
  select jsonb_build_object(
    'settings', (
      select jsonb_strip_nulls(jsonb_build_object(
        'name', s.name, 'description', s.description, 'currency', s.currency, 'locale', s.locale,
        'lowStockThreshold', s.low_stock_threshold, 'orderPrefix', s.order_prefix,
        'contact', s.contact, 'footer', s.footer, 'checkout', s.checkout, 'shipping', s.shipping, 'policies', s.policies,
        'rail', s.rail || jsonb_build_object('placements', coalesce((
          select jsonb_agg(jsonb_build_object('productId', r.product_id, 'colorwayId', r.colorway_id) order by r.position)
          from public.rail_placements r join public.products p on p.id = r.product_id
          where ((select admin from flags) or p.status = 'active')
            and exists (select 1 from public.colorway_media cm where cm.product_id = r.product_id and cm.colorway_id = r.colorway_id and cm.role = 'front')
        ), '[]'::jsonb)),
        'home', s.home || jsonb_build_object('featuredProductIds', coalesce((
          select jsonb_agg(f.product_id order by f.position)
          from public.featured_products f join public.products p on p.id = f.product_id
          where (select admin from flags) or p.status = 'active'
        ), '[]'::jsonb))
      ))
      from settings s
    ),
    'categories', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'label', c.label) order by c.position, c.label) from public.categories c), '[]'::jsonb),
    'media', coalesce((
      select jsonb_object_agg(m.id, public.media_json(m))
      from public.media m where (select admin from flags) or public.media_is_public(m.id)
    ), '{}'::jsonb),
    'products', coalesce((select jsonb_agg(d.doc order by d.name) from product_docs d), '[]'::jsonb),
    'collections', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', c.id, 'slug', c.slug, 'title', c.title, 'season', c.season, 'summary', c.summary,
        'published', case when (select admin from flags) then c.published end,
        'productIds', coalesce((
          select jsonb_agg(cp.product_id order by cp.position)
          from public.collection_products cp join public.products p on p.id = cp.product_id
          where cp.collection_id = c.id and ((select admin from flags) or p.status = 'active')
        ), '[]'::jsonb)
      )) order by c.position, c.title)
      from public.collections c where (select admin from flags) or c.published
    ), '[]'::jsonb),
    'lookbooks', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', b.id, 'title', b.title, 'season', b.season, 'summary', b.summary,
        'published', case when (select admin from flags) then b.published end,
        'spreads', coalesce((
          select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'id', sp.id, 'layout', sp.layout, 'note', sp.note,
            'published', case when (select admin from flags) then sp.published end,
            'looks', coalesce((
              select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                'id', l.id, 'title', l.title, 'caption', l.caption, 'tone', l.tone, 'kind', l.kind, 'mediaId', l.media_id,
                'published', case when (select admin from flags) then l.published end,
                'pieces', coalesce((
                  select jsonb_agg(jsonb_build_object('productId', lp.product_id, 'colorwayId', lp.colorway_id, 'view', lp.view) order by lp.position)
                  from public.look_pieces lp join public.products p on p.id = lp.product_id
                  where lp.look_id = l.id and ((select admin from flags) or p.status = 'active')
                ), '[]'::jsonb)
              )) order by l.position)
              from public.looks l where l.spread_id = sp.id and ((select admin from flags) or l.published)
            ), '[]'::jsonb)
          )) order by sp.position)
          from public.lookbook_spreads sp where sp.lookbook_id = b.id and ((select admin from flags) or sp.published)
        ), '[]'::jsonb)
      )) order by b.id)
      from public.lookbooks b where (select admin from flags) or b.published
    ), '[]'::jsonb)
  );
$$;

-- Runs with the caller's rights, so row level security filters every row as
-- well: even p_admin = true only returns drafts to an administrator.
revoke all on function public.catalog_json(boolean) from public;
grant execute on function public.catalog_json(boolean) to anon, authenticated;
revoke all on function public.media_json(public.media) from public;
grant execute on function public.media_json(public.media) to anon, authenticated;

create or replace function public.storefront_catalog()
returns jsonb
language sql
stable
set search_path = ''
as $$
  select public.catalog_json(false);
$$;

revoke all on function public.storefront_catalog() from public;
grant execute on function public.storefront_catalog() to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Checkout

create or replace function public.place_order(p_order jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  s public.store_settings;
  method jsonb;
  contact jsonb := coalesce(p_order -> 'contact', '{}'::jsonb);
  address jsonb := coalesce(p_order -> 'address', '{}'::jsonb);
  v_email text := lower(btrim(coalesce(contact ->> 'email', '')));
  v_name text := btrim(coalesce(contact ->> 'name', ''));
  v_phone text := btrim(coalesce(contact ->> 'phone', ''));
  v_line1 text := btrim(coalesce(address ->> 'line1', ''));
  v_line2 text := btrim(coalesce(address ->> 'line2', ''));
  v_city text := btrim(coalesce(address ->> 'city', ''));
  v_region text := btrim(coalesce(address ->> 'region', ''));
  v_postal text := btrim(coalesce(address ->> 'postalCode', ''));
  v_country text := btrim(coalesce(address ->> 'country', ''));
  v_notes text := btrim(coalesce(p_order ->> 'notes', ''));
  requested jsonb;
  line record;
  short jsonb := '[]'::jsonb;
  v_subtotal integer := 0;
  v_shipping integer := 0;
  flat integer;
  free_over integer;
  v_order public.orders;
  v_position integer := 0;
begin
  select * into s from public.store_settings where id;
  if s is null or coalesce((s.checkout ->> 'enabled')::boolean, false) is not true then
    raise exception 'checkout_unavailable' using hint = 'Checkout is not enabled for this store.';
  end if;

  select m into method from jsonb_array_elements(coalesce(s.checkout -> 'methods', '[]'::jsonb)) m
   where m ->> 'id' = p_order ->> 'paymentMethod' and coalesce((m ->> 'enabled')::boolean, false);
  if method is null then
    raise exception 'invalid_payment_method';
  end if;

  -- Contact and delivery details.
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or char_length(v_email) > 254 then raise exception 'invalid_contact' using detail = 'email'; end if;
  if char_length(v_name) not between 1 and 120 then raise exception 'invalid_contact' using detail = 'name'; end if;
  if char_length(v_phone) not between 5 and 40 or v_phone !~ '^[0-9+()\-.\s]+$' then raise exception 'invalid_contact' using detail = 'phone'; end if;
  if char_length(v_line1) not between 1 and 200 then raise exception 'invalid_contact' using detail = 'line1'; end if;
  if char_length(v_line2) > 200 then raise exception 'invalid_contact' using detail = 'line2'; end if;
  if char_length(v_city) not between 1 and 100 then raise exception 'invalid_contact' using detail = 'city'; end if;
  if char_length(v_region) > 100 then raise exception 'invalid_contact' using detail = 'region'; end if;
  if char_length(v_postal) not between 1 and 20 then raise exception 'invalid_contact' using detail = 'postalCode'; end if;
  if char_length(v_country) not between 2 and 60 then raise exception 'invalid_contact' using detail = 'country'; end if;
  if char_length(v_notes) > 1000 then raise exception 'invalid_contact' using detail = 'notes'; end if;

  -- Items: 1–25 distinct SKUs, 1–10 of each. Repeated SKUs are merged.
  if jsonb_typeof(p_order -> 'items') <> 'array' or jsonb_array_length(p_order -> 'items') not between 1 and 25 then
    raise exception 'invalid_items';
  end if;
  begin
    select jsonb_object_agg(sku, quantity) into requested
      from (
        select i ->> 'sku' as sku, sum((i ->> 'quantity')::integer) as quantity
          from jsonb_array_elements(p_order -> 'items') i
         group by i ->> 'sku'
      ) merged;
  exception when others then
    raise exception 'invalid_items';
  end;
  if exists (select 1 from jsonb_each_text(requested) r where r.key is null or r.value::integer not between 1 and 10) then
    raise exception 'invalid_items';
  end if;

  -- Lock every requested variant in a fixed order, so concurrent checkouts
  -- queue behind each other instead of deadlocking or overselling.
  perform 1 from public.variants v where v.sku in (select jsonb_object_keys(requested)) order by v.sku for update;

  for line in
    select r.key as sku, r.value::integer as quantity, v.stock, v.product_id, v.colorway_id, v.size,
           p.name as product_name, p.price, p.status, c.name as colorway_name,
           (select m.src from public.colorway_media cm join public.media m on m.id = cm.media_id
             where cm.product_id = v.product_id and cm.colorway_id = v.colorway_id and cm.role = 'front') as image_src
      from jsonb_each_text(requested) r
      left join public.variants v on v.sku = r.key
      left join public.products p on p.id = v.product_id
      left join public.colorways c on c.product_id = v.product_id and c.id = v.colorway_id
     order by r.key
  loop
    if line.product_id is null then raise exception 'unknown_item' using detail = line.sku; end if;
    if line.status <> 'active' then raise exception 'unavailable_item' using detail = line.sku; end if;
    if line.stock < line.quantity then
      short := short || jsonb_build_object('sku', line.sku, 'requested', line.quantity, 'available', line.stock);
    end if;
    v_subtotal := v_subtotal + line.price * line.quantity;
  end loop;

  if jsonb_array_length(short) > 0 then
    raise exception 'insufficient_stock' using detail = short::text;
  end if;

  flat := greatest(coalesce((s.shipping ->> 'flatRate')::integer, 0), 0);
  free_over := (s.shipping ->> 'freeOver')::integer;
  v_shipping := case when free_over is not null and v_subtotal >= free_over then 0 else flat end;

  insert into public.orders (
    reference, payment_method, payment_method_label, payment_instructions, currency,
    subtotal, shipping, total, email, name, phone, address, notes
  ) values (
    s.order_prefix || '-' || nextval('public.order_number_seq'),
    method ->> 'id', coalesce(method ->> 'label', method ->> 'id'), coalesce(method ->> 'instructions', ''), s.currency,
    v_subtotal, v_shipping, v_subtotal + v_shipping, v_email, v_name, v_phone,
    jsonb_build_object('line1', v_line1, 'line2', v_line2, 'city', v_city, 'region', v_region, 'postalCode', v_postal, 'country', v_country),
    v_notes
  ) returning * into v_order;

  for line in
    select r.key as sku, r.value::integer as quantity, v.product_id, v.colorway_id, v.size,
           p.name as product_name, p.price, c.name as colorway_name, c.position as colorway_position,
           (select m.src from public.colorway_media cm join public.media m on m.id = cm.media_id
             where cm.product_id = v.product_id and cm.colorway_id = v.colorway_id and cm.role = 'front') as image_src
      from jsonb_each_text(requested) r
      join public.variants v on v.sku = r.key
      join public.products p on p.id = v.product_id
      join public.colorways c on c.product_id = v.product_id and c.id = v.colorway_id
     order by p.name, c.position, array_position(p.sizes, v.size)
  loop
    v_position := v_position + 1;
    insert into public.order_items (order_id, position, sku, product_id, colorway_id, product_name, colorway_name, size, unit_price, quantity, line_total, image_src)
    values (v_order.id, v_position, line.sku, line.product_id, line.colorway_id, line.product_name, line.colorway_name, line.size, line.price, line.quantity, line.price * line.quantity, line.image_src);
    update public.variants set stock = stock - line.quantity where sku = line.sku;
  end loop;

  insert into public.order_events (order_id, kind, to_value) values (v_order.id, 'placed', 'pending');

  return jsonb_build_object(
    'reference', v_order.reference,
    'status', v_order.status,
    'paymentStatus', v_order.payment_status,
    'paymentMethod', v_order.payment_method_label,
    'paymentInstructions', v_order.payment_instructions,
    'currency', v_order.currency,
    'subtotal', v_order.subtotal,
    'shipping', v_order.shipping,
    'total', v_order.total,
    'email', v_order.email,
    'createdAt', v_order.created_at,
    'items', (
      select jsonb_agg(jsonb_build_object(
        'name', i.product_name, 'colorway', i.colorway_name, 'size', i.size,
        'quantity', i.quantity, 'unitPrice', i.unit_price, 'lineTotal', i.line_total, 'imageSrc', i.image_src
      ) order by i.position)
      from public.order_items i where i.order_id = v_order.id
    )
  );
end;
$$;

revoke all on function public.place_order(jsonb) from public;
grant execute on function public.place_order(jsonb) to anon, authenticated;


-- ===== 20261028120400_admin_api.sql =====

-- STILLFORM · admin API
--
-- Everything the dashboard changes goes through these functions. Each one
-- checks public.is_admin() first and validates its input, and each save is a
-- single transaction, so a product is never left half-saved. Functions that
-- only touch catalogue tables run with the caller's rights (row level
-- security applies as a second check); the order functions run as the owner
-- because clients have no write access to orders at all.

create or replace function public.assert_admin()
returns void
language plpgsql
stable
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
end;
$$;

create or replace function public.admin_catalog()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
begin
  perform public.assert_admin();
  return public.catalog_json(true) || jsonb_build_object(
    'privateSettings', (
      select jsonb_build_object('orderNotificationEmail', ps.order_notification_email, 'notes', ps.notes)
      from public.store_private_settings ps where ps.id
    )
  );
end;
$$;

-- A product can go live once it has a price, sizes, a colourway, and a front
-- photograph for every colourway.
create or replace function public.assert_publishable(p_product text)
returns void
language plpgsql
stable
set search_path = ''
as $$
declare
  missing text;
begin
  if not exists (select 1 from public.products where id = p_product and price > 0 and cardinality(sizes) > 0) then
    raise exception 'not_publishable' using detail = 'price_or_sizes';
  end if;
  if not exists (select 1 from public.colorways where product_id = p_product) then
    raise exception 'not_publishable' using detail = 'colorways';
  end if;
  select c.name into missing from public.colorways c
   where c.product_id = p_product
     and not exists (select 1 from public.colorway_media cm where cm.product_id = c.product_id and cm.colorway_id = c.id and cm.role = 'front')
   limit 1;
  if missing is not null then
    raise exception 'not_publishable' using detail = 'front_image:' || missing;
  end if;
end;
$$;

create or replace function public.sku_for(p_product text, p_colorway text, p_size text)
returns text
language sql
immutable
set search_path = ''
as $$
  select upper(trim(both '-' from regexp_replace(p_product || '-' || p_colorway || '-' || p_size, '[^A-Za-z0-9]+', '-', 'g')));
$$;

-- ---------------------------------------------------------------------------
-- Products

create or replace function public.admin_save_product(p jsonb)
returns jsonb
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_slug text := lower(btrim(coalesce(p ->> 'slug', '')));
  v_id text := coalesce(nullif(btrim(p ->> 'id'), ''), lower(btrim(coalesce(p ->> 'slug', ''))));
  v_is_new boolean := coalesce((p ->> 'isNew')::boolean, false);
  v_status text := coalesce(p ->> 'status', 'draft');
  v_price integer;
  v_sizes text[];
  cw jsonb;
  cw_id text;
  cw_ids text[] := '{}';
  skus text[] := '{}';
  v_size text;
  v_sku text;
  v_desired integer;
  v_base integer;
  v_current integer;
  v_pos integer := 0;
  r text;
  item text;
  i integer;
begin
  perform public.assert_admin();

  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(v_slug) > 80 then raise exception 'invalid_product' using detail = 'slug'; end if;
  if v_status not in ('draft', 'active', 'archived') then raise exception 'invalid_product' using detail = 'status'; end if;
  if char_length(btrim(coalesce(p ->> 'name', ''))) not between 1 and 120 then raise exception 'invalid_product' using detail = 'name'; end if;
  begin
    v_price := (p ->> 'price')::integer;
  exception when others then
    raise exception 'invalid_product' using detail = 'price';
  end;
  if v_price is null or v_price not between 0 and 100000000 then raise exception 'invalid_product' using detail = 'price'; end if;
  if not exists (select 1 from public.categories where id = p ->> 'category') then raise exception 'invalid_product' using detail = 'category'; end if;

  select coalesce(array_agg(size order by ord), '{}') into v_sizes
    from (select btrim(value) as size, min(ordinality) as ord
            from jsonb_array_elements_text(coalesce(p -> 'sizes', '[]'::jsonb)) with ordinality
           where btrim(value) <> '' group by btrim(value)) s;
  if cardinality(v_sizes) > 12 or exists (select 1 from unnest(v_sizes) z where char_length(z) > 24) then
    raise exception 'invalid_product' using detail = 'sizes';
  end if;
  if jsonb_typeof(p -> 'colorways') <> 'array' or jsonb_array_length(p -> 'colorways') not between 1 and 12 then
    raise exception 'invalid_product' using detail = 'colorways';
  end if;

  if v_is_new then
    if exists (select 1 from public.products where id = v_id or slug = v_slug) then raise exception 'slug_taken'; end if;
  else
    if not exists (select 1 from public.products where id = v_id) then raise exception 'product_not_found'; end if;
    if exists (select 1 from public.products where slug = v_slug and id <> v_id) then raise exception 'slug_taken'; end if;
  end if;

  insert into public.products as t (id, slug, name, category_id, status, price, summary, description, details, composition, care, fit, fabric, sizes)
  values (
    v_id, v_slug, btrim(p ->> 'name'), p ->> 'category', v_status, v_price,
    btrim(coalesce(p ->> 'summary', '')), btrim(coalesce(p ->> 'description', '')),
    coalesce(array(select btrim(x) from jsonb_array_elements_text(coalesce(p -> 'details', '[]'::jsonb)) x where btrim(x) <> ''), '{}'),
    btrim(coalesce(p ->> 'composition', '')),
    coalesce(array(select btrim(x) from jsonb_array_elements_text(coalesce(p -> 'care', '[]'::jsonb)) x where btrim(x) <> ''), '{}'),
    btrim(coalesce(p ->> 'fit', '')), nullif(btrim(coalesce(p ->> 'fabric', '')), ''), v_sizes
  )
  on conflict (id) do update set
    slug = excluded.slug, name = excluded.name, category_id = excluded.category_id, status = excluded.status,
    price = excluded.price, summary = excluded.summary, description = excluded.description, details = excluded.details,
    composition = excluded.composition, care = excluded.care, fit = excluded.fit, fabric = excluded.fabric, sizes = excluded.sizes;

  -- Colourways and their photographs.
  for cw in select value from jsonb_array_elements(p -> 'colorways') loop
    v_pos := v_pos + 1;
    cw_id := lower(btrim(coalesce(cw ->> 'id', '')));
    if cw_id !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(cw_id) > 60 then raise exception 'invalid_product' using detail = 'colorway_id'; end if;
    if cw_id = any (cw_ids) then raise exception 'invalid_product' using detail = 'colorway_duplicate'; end if;
    if char_length(btrim(coalesce(cw ->> 'name', ''))) not between 1 and 60 then raise exception 'invalid_product' using detail = 'colorway_name'; end if;
    if coalesce(cw ->> 'swatch', '') !~ '^#[0-9a-fA-F]{6}$' then raise exception 'invalid_product' using detail = 'colorway_swatch'; end if;
    cw_ids := cw_ids || cw_id;
    insert into public.colorways (product_id, id, name, swatch, position)
    values (v_id, cw_id, btrim(cw ->> 'name'), cw ->> 'swatch', v_pos)
    on conflict (product_id, id) do update set name = excluded.name, swatch = excluded.swatch, position = excluded.position;
  end loop;
  delete from public.colorways where product_id = v_id and not (id = any (cw_ids));
  delete from public.colorway_media where product_id = v_id;

  for cw in select value from jsonb_array_elements(p -> 'colorways') loop
    cw_id := lower(btrim(cw ->> 'id'));
    foreach r in array array['front', 'back', 'side'] loop
      if nullif(cw -> 'media' ->> r, '') is not null then
        insert into public.colorway_media (product_id, colorway_id, role, position, media_id) values (v_id, cw_id, r, 0, cw -> 'media' ->> r);
      end if;
    end loop;
    foreach r in array array['gallery', 'lifestyle', 'details'] loop
      i := 0;
      for item in select value from jsonb_array_elements_text(coalesce(cw -> 'media' -> r, '[]'::jsonb)) loop
        insert into public.colorway_media (product_id, colorway_id, role, position, media_id)
        values (v_id, cw_id, case r when 'details' then 'detail' else r end, i, item);
        i := i + 1;
      end loop;
    end loop;

    -- Inventory. "stockBase" is the count the editor was showing; applying the
    -- difference keeps orders placed while the form was open.
    foreach v_size in array v_sizes loop
      v_sku := public.sku_for(v_id, cw_id, v_size);
      if exists (select 1 from public.variants where sku = v_sku and (product_id <> v_id or colorway_id <> cw_id)) then
        raise exception 'sku_conflict' using detail = v_sku;
      end if;
      begin
        v_desired := coalesce((cw -> 'stock' ->> v_size)::integer, 0);
        v_base := (cw -> 'stockBase' ->> v_size)::integer;
      exception when others then
        raise exception 'invalid_product' using detail = 'stock';
      end;
      if v_desired not between 0 and 1000000 then raise exception 'invalid_product' using detail = 'stock'; end if;
      select stock into v_current from public.variants where sku = v_sku for update;
      if v_current is not null and v_base is not null then
        v_desired := greatest(0, v_current + (v_desired - v_base));
      end if;
      insert into public.variants (sku, product_id, colorway_id, size, stock) values (v_sku, v_id, cw_id, v_size, v_desired)
      on conflict (sku) do update set stock = excluded.stock, size = excluded.size;
      skus := skus || v_sku;
    end loop;

    -- Rail membership.
    if coalesce((cw ->> 'onRail')::boolean, false) then
      insert into public.rail_placements (product_id, colorway_id, position)
      values (v_id, cw_id, coalesce((select max(position) + 1 from public.rail_placements), 0))
      on conflict (product_id, colorway_id) do nothing;
    else
      delete from public.rail_placements where product_id = v_id and colorway_id = cw_id;
    end if;
  end loop;
  delete from public.variants where product_id = v_id and not (sku = any (skus));

  -- Featured on the homepage.
  if coalesce((p ->> 'featured')::boolean, false) then
    insert into public.featured_products (product_id, position)
    values (v_id, coalesce((select max(position) + 1 from public.featured_products), 0))
    on conflict (product_id) do nothing;
  else
    delete from public.featured_products where product_id = v_id;
  end if;

  -- Collections.
  delete from public.collection_products
   where product_id = v_id and not (collection_id in (select jsonb_array_elements_text(coalesce(p -> 'collectionIds', '[]'::jsonb))));
  insert into public.collection_products (collection_id, product_id, position)
  select c, v_id, coalesce((select max(position) + 1 from public.collection_products where collection_id = c), 0)
    from jsonb_array_elements_text(coalesce(p -> 'collectionIds', '[]'::jsonb)) c
  on conflict (collection_id, product_id) do nothing;

  -- Wear it with: up to six, in order.
  delete from public.product_pairings where product_id = v_id;
  insert into public.product_pairings (product_id, paired_product_id, position)
  select v_id, x.value, x.ordinality::integer
    from jsonb_array_elements_text(coalesce(p -> 'pairsWith', '[]'::jsonb)) with ordinality x
   where x.value <> v_id and exists (select 1 from public.products where id = x.value)
   limit 6
  on conflict do nothing;

  if v_status = 'active' then
    perform public.assert_publishable(v_id);
  end if;

  return jsonb_build_object('id', v_id, 'slug', v_slug, 'status', v_status);
end;
$$;

create or replace function public.admin_set_product_status(p_product text, p_status text)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  perform public.assert_admin();
  if p_status not in ('draft', 'active', 'archived') then raise exception 'invalid_product' using detail = 'status'; end if;
  update public.products set status = p_status where id = p_product;
  if not found then raise exception 'product_not_found'; end if;
  if p_status = 'active' then perform public.assert_publishable(p_product); end if;
end;
$$;

create or replace function public.admin_delete_product(p_product text)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  perform public.assert_admin();
  -- Order items keep their own snapshot, so past orders are unaffected.
  delete from public.products where id = p_product;
  if not found then raise exception 'product_not_found'; end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Rail, featured products and collections

create or replace function public.admin_set_rail(p_placements jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  item jsonb;
  pos integer := 0;
begin
  perform public.assert_admin();
  if jsonb_typeof(p_placements) <> 'array' or jsonb_array_length(p_placements) > 24 then
    raise exception 'invalid_rail' using detail = 'A rail holds up to 24 pieces.';
  end if;
  delete from public.rail_placements where true;
  for item in select value from jsonb_array_elements(p_placements) loop
    if not exists (
      select 1 from public.colorway_media
       where product_id = item ->> 'productId' and colorway_id = item ->> 'colorwayId' and role = 'front'
    ) then
      raise exception 'invalid_rail' using detail = 'front_image:' || (item ->> 'productId') || '/' || (item ->> 'colorwayId');
    end if;
    insert into public.rail_placements (product_id, colorway_id, position)
    values (item ->> 'productId', item ->> 'colorwayId', pos)
    on conflict (product_id, colorway_id) do nothing;
    pos := pos + 1;
  end loop;
end;
$$;

create or replace function public.admin_set_featured(p_products jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  perform public.assert_admin();
  delete from public.featured_products where true;
  insert into public.featured_products (product_id, position)
  select x.value, x.ordinality::integer
    from jsonb_array_elements_text(coalesce(p_products, '[]'::jsonb)) with ordinality x
   where exists (select 1 from public.products where id = x.value)
  on conflict (product_id) do nothing;
end;
$$;

create or replace function public.admin_save_collection(p jsonb)
returns jsonb
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_slug text := lower(btrim(coalesce(p ->> 'slug', '')));
  v_id text := coalesce(nullif(btrim(p ->> 'id'), ''), lower(btrim(coalesce(p ->> 'slug', ''))));
begin
  perform public.assert_admin();
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'invalid_collection' using detail = 'slug'; end if;
  if char_length(btrim(coalesce(p ->> 'title', ''))) not between 1 and 120 then raise exception 'invalid_collection' using detail = 'title'; end if;
  if coalesce((p ->> 'isNew')::boolean, false) and exists (select 1 from public.collections where id = v_id or slug = v_slug) then
    raise exception 'slug_taken';
  end if;
  insert into public.collections (id, slug, title, season, summary, published, position)
  values (v_id, v_slug, btrim(p ->> 'title'), btrim(coalesce(p ->> 'season', '')), btrim(coalesce(p ->> 'summary', '')),
          coalesce((p ->> 'published')::boolean, true), coalesce((select max(position) + 1 from public.collections), 0))
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, season = excluded.season,
    summary = excluded.summary, published = excluded.published;
  delete from public.collection_products where collection_id = v_id;
  insert into public.collection_products (collection_id, product_id, position)
  select v_id, x.value, x.ordinality::integer
    from jsonb_array_elements_text(coalesce(p -> 'productIds', '[]'::jsonb)) with ordinality x
   where exists (select 1 from public.products where id = x.value)
  on conflict do nothing;
  return jsonb_build_object('id', v_id);
end;
$$;

create or replace function public.admin_delete_collection(p_collection text)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  perform public.assert_admin();
  delete from public.collections where id = p_collection;
end;
$$;

-- ---------------------------------------------------------------------------
-- Lookbook. The layouts are fixed templates; each needs a set number of frames.

create or replace function public.admin_save_lookbook(p jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_id text := btrim(coalesce(p ->> 'id', ''));
  spread jsonb;
  look jsonb;
  piece jsonb;
  spread_ids text[] := '{}';
  look_ids text[] := '{}';
  s_pos integer := 0;
  l_pos integer;
  p_pos integer;
  n integer;
  layout text;
begin
  perform public.assert_admin();
  if v_id !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'invalid_lookbook' using detail = 'id'; end if;
  if char_length(btrim(coalesce(p ->> 'title', ''))) not between 1 and 120 then raise exception 'invalid_lookbook' using detail = 'title'; end if;

  insert into public.lookbooks (id, title, season, summary, published)
  values (v_id, btrim(p ->> 'title'), btrim(coalesce(p ->> 'season', '')), btrim(coalesce(p ->> 'summary', '')), coalesce((p ->> 'published')::boolean, true))
  on conflict (id) do update set title = excluded.title, season = excluded.season, summary = excluded.summary, published = excluded.published;

  for spread in select value from jsonb_array_elements(coalesce(p -> 'spreads', '[]'::jsonb)) loop
    s_pos := s_pos + 1;
    layout := spread ->> 'layout';
    n := jsonb_array_length(coalesce(spread -> 'looks', '[]'::jsonb));
    if layout not in ('cinematic', 'pair', 'pair-flip', 'wide', 'materials') then raise exception 'invalid_lookbook' using detail = 'layout'; end if;
    if (layout in ('cinematic', 'wide') and n <> 1) or (layout in ('pair', 'pair-flip') and n <> 2) or (layout = 'materials' and n not between 2 and 3) then
      raise exception 'invalid_lookbook' using detail = 'frames:' || layout;
    end if;
    if coalesce(spread ->> 'id', '') = '' or (spread ->> 'id') = any (spread_ids) then raise exception 'invalid_lookbook' using detail = 'spread_id'; end if;
    spread_ids := spread_ids || (spread ->> 'id');
    if exists (select 1 from public.lookbook_spreads where id = spread ->> 'id' and lookbook_id <> v_id) then
      raise exception 'invalid_lookbook' using detail = 'spread_id';
    end if;
    insert into public.lookbook_spreads (id, lookbook_id, layout, note, position, published)
    values (spread ->> 'id', v_id, layout, nullif(btrim(coalesce(spread ->> 'note', '')), ''), s_pos, coalesce((spread ->> 'published')::boolean, true))
    on conflict (id) do update set layout = excluded.layout, note = excluded.note, position = excluded.position, published = excluded.published;

    l_pos := 0;
    for look in select value from jsonb_array_elements(spread -> 'looks') loop
      l_pos := l_pos + 1;
      if coalesce(look ->> 'id', '') = '' or (look ->> 'id') = any (look_ids) then raise exception 'invalid_lookbook' using detail = 'look_id'; end if;
      if char_length(btrim(coalesce(look ->> 'title', ''))) not between 1 and 120 then raise exception 'invalid_lookbook' using detail = 'look_title'; end if;
      look_ids := look_ids || (look ->> 'id');
      insert into public.looks (id, spread_id, title, caption, tone, kind, media_id, position, published)
      values (look ->> 'id', spread ->> 'id', btrim(look ->> 'title'), btrim(coalesce(look ->> 'caption', '')),
              coalesce(look ->> 'tone', 'plaster'), coalesce(look ->> 'kind', 'campaign'), nullif(look ->> 'mediaId', ''), l_pos,
              coalesce((look ->> 'published')::boolean, true))
      on conflict (id) do update set spread_id = excluded.spread_id, title = excluded.title, caption = excluded.caption,
        tone = excluded.tone, kind = excluded.kind, media_id = excluded.media_id, position = excluded.position, published = excluded.published;
      delete from public.look_pieces where look_id = look ->> 'id';
      p_pos := 0;
      for piece in select value from jsonb_array_elements(coalesce(look -> 'pieces', '[]'::jsonb)) loop
        p_pos := p_pos + 1;
        insert into public.look_pieces (look_id, position, product_id, colorway_id, view)
        values (look ->> 'id', p_pos, piece ->> 'productId', piece ->> 'colorwayId', coalesce(piece ->> 'view', 'front'));
      end loop;
    end loop;
  end loop;

  delete from public.looks l using public.lookbook_spreads s
   where s.id = l.spread_id and s.lookbook_id = v_id and not (l.id = any (look_ids));
  delete from public.lookbook_spreads where lookbook_id = v_id and not (id = any (spread_ids));
end;
$$;

-- ---------------------------------------------------------------------------
-- Media library

create or replace function public.admin_create_media(p jsonb)
returns jsonb
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_media public.media;
begin
  perform public.assert_admin();
  if coalesce(p ->> 'src', '') !~ '^(https?://|/)' then raise exception 'invalid_media' using detail = 'src'; end if;
  if coalesce(p ->> 'storagePath', '') <> '' and (p ->> 'storagePath') !~ '^[a-z0-9-]+/[A-Za-z0-9._-]+$' then
    raise exception 'invalid_media' using detail = 'storagePath';
  end if;
  insert into public.media (id, src, storage_path, alt, width, height, origin, variants, focus)
  values (
    'upload-' || replace(gen_random_uuid()::text, '-', ''),
    p ->> 'src', nullif(p ->> 'storagePath', ''), left(btrim(coalesce(p ->> 'alt', '')), 500),
    (p ->> 'width')::integer, (p ->> 'height')::integer, 'uploaded',
    coalesce(p -> 'variants', '[]'::jsonb), nullif(p ->> 'focus', '')
  ) returning * into v_media;
  return public.media_json(v_media);
end;
$$;

create or replace function public.admin_update_media(p_media text, p_alt text, p_focus text)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  perform public.assert_admin();
  update public.media set alt = left(btrim(coalesce(p_alt, '')), 500), focus = nullif(p_focus, '') where id = p_media;
end;
$$;

-- Media not used by any product, look or setting.
create or replace function public.admin_unused_media()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
begin
  perform public.assert_admin();
  return coalesce((
    select jsonb_agg(public.media_json(m) order by m.created_at)
      from public.media m
     where not exists (select 1 from public.colorway_media cm where cm.media_id = m.id)
       and not exists (select 1 from public.looks l where l.media_id = m.id)
       and not exists (select 1 from public.store_settings s where s.home #>> '{statement,mediaId}' = m.id)
  ), '[]'::jsonb);
end;
$$;

-- Deletes unused media rows and returns their storage paths, so the caller can
-- remove the files. Rows still in use are left alone; a file is only ever
-- orphaned, never a reference broken.
create or replace function public.admin_delete_media(p_ids jsonb)
returns jsonb
language plpgsql
volatile
set search_path = ''
as $$
declare
  removed jsonb;
begin
  perform public.assert_admin();
  with gone as (
    delete from public.media m
     where m.id in (select jsonb_array_elements_text(coalesce(p_ids, '[]'::jsonb)))
       and not exists (select 1 from public.colorway_media cm where cm.media_id = m.id)
       and not exists (select 1 from public.looks l where l.media_id = m.id)
       and not exists (select 1 from public.store_settings s where s.home #>> '{statement,mediaId}' = m.id)
    returning m.id, m.storage_path, m.variants
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'storagePath', storage_path, 'variants', variants)), '[]'::jsonb) into removed from gone;
  return removed;
end;
$$;

-- ---------------------------------------------------------------------------
-- Settings

create or replace function public.admin_save_settings(p_public jsonb, p_private jsonb)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  methods jsonb := coalesce(p_public #> '{checkout,methods}', '[]'::jsonb);
  enabled boolean := coalesce((p_public #>> '{checkout,enabled}')::boolean, false);
  flat integer;
  free_over integer;
begin
  perform public.assert_admin();
  if char_length(btrim(coalesce(p_public ->> 'name', ''))) not between 1 and 60 then raise exception 'invalid_settings' using detail = 'name'; end if;
  if coalesce(p_public ->> 'currency', '') !~ '^[A-Z]{3}$' then raise exception 'invalid_settings' using detail = 'currency'; end if;
  if jsonb_typeof(methods) <> 'array' or exists (
    select 1 from jsonb_array_elements(methods) m
     where m ->> 'id' not in ('cod', 'bank-transfer', 'pickup')
        or char_length(btrim(coalesce(m ->> 'label', ''))) not between 1 and 60
        or char_length(coalesce(m ->> 'instructions', '')) > 600
  ) then
    raise exception 'invalid_settings' using detail = 'checkout_methods';
  end if;
  if enabled and not exists (select 1 from jsonb_array_elements(methods) m where coalesce((m ->> 'enabled')::boolean, false)) then
    raise exception 'invalid_settings' using detail = 'checkout_needs_method';
  end if;
  begin
    flat := coalesce((p_public #>> '{shipping,flatRate}')::integer, 0);
    free_over := (p_public #>> '{shipping,freeOver}')::integer;
  exception when others then
    raise exception 'invalid_settings' using detail = 'shipping';
  end;
  if flat not between 0 and 10000000 or (free_over is not null and free_over not between 0 and 100000000) then
    raise exception 'invalid_settings' using detail = 'shipping';
  end if;

  update public.store_settings set
    name = btrim(p_public ->> 'name'),
    description = left(btrim(coalesce(p_public ->> 'description', '')), 600),
    currency = p_public ->> 'currency',
    locale = coalesce(nullif(p_public ->> 'locale', ''), locale),
    low_stock_threshold = coalesce((p_public ->> 'lowStockThreshold')::integer, low_stock_threshold),
    contact = coalesce(p_public -> 'contact', '{}'::jsonb),
    rail = coalesce(p_public -> 'rail', rail) - 'placements',
    home = coalesce(p_public -> 'home', home) - 'featuredProductIds',
    footer = coalesce(p_public -> 'footer', footer),
    checkout = jsonb_build_object('enabled', enabled, 'methods', methods),
    shipping = jsonb_build_object('flatRate', flat, 'freeOver', free_over, 'note', left(coalesce(p_public #>> '{shipping,note}', ''), 600)),
    policies = coalesce(p_public -> 'policies', '{}'::jsonb)
  where id;

  if p_private is not null then
    update public.store_private_settings set
      order_notification_email = nullif(btrim(coalesce(p_private ->> 'orderNotificationEmail', '')), ''),
      notes = left(coalesce(p_private ->> 'notes', ''), 4000)
    where id;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Orders

create or replace function public.order_json(o public.orders, p_items boolean)
returns jsonb
language sql
stable
set search_path = ''
as $$
  select jsonb_build_object(
    'id', o.id, 'reference', o.reference, 'status', o.status, 'paymentStatus', o.payment_status,
    'paymentMethod', o.payment_method, 'paymentMethodLabel', o.payment_method_label,
    'currency', o.currency, 'subtotal', o.subtotal, 'shipping', o.shipping, 'total', o.total,
    'email', o.email, 'name', o.name, 'phone', o.phone, 'address', o.address, 'notes', o.notes,
    'createdAt', o.created_at, 'updatedAt', o.updated_at, 'restockedAt', o.restocked_at,
    'itemCount', (select coalesce(sum(quantity), 0) from public.order_items i where i.order_id = o.id)
  ) || case when p_items then jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'sku', i.sku, 'productId', i.product_id, 'colorwayId', i.colorway_id, 'name', i.product_name,
        'colorway', i.colorway_name, 'size', i.size, 'unitPrice', i.unit_price, 'quantity', i.quantity,
        'lineTotal', i.line_total, 'imageSrc', i.image_src
      ) order by i.position) from public.order_items i where i.order_id = o.id
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'note', e.note, 'createdAt', e.created_at) order by e.created_at, e.id)
      from public.order_events e where e.order_id = o.id
    ), '[]'::jsonb)
  ) else '{}'::jsonb end;
$$;

create or replace function public.admin_orders(p_search text default null, p_status text default null, p_limit integer default 50, p_offset integer default 0)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform public.assert_admin();
  return jsonb_build_object(
    'total', (
      select count(*) from public.orders o
       where (p_status is null or o.status = p_status)
         and (q is null or o.reference ilike '%' || q || '%' or o.email ilike '%' || q || '%' or o.name ilike '%' || q || '%')
    ),
    'orders', coalesce((
      select jsonb_agg(public.order_json(o, false) order by o.created_at desc)
        from (
          select * from public.orders o
           where (p_status is null or o.status = p_status)
             and (q is null or o.reference ilike '%' || q || '%' or o.email ilike '%' || q || '%' or o.name ilike '%' || q || '%')
           order by o.created_at desc
           limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)
        ) o
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.admin_order(p_reference text)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  o public.orders;
begin
  perform public.assert_admin();
  select * into o from public.orders where reference = p_reference;
  if o is null then raise exception 'order_not_found'; end if;
  return public.order_json(o, true);
end;
$$;

create or replace function public.admin_update_order(p_reference text, p_status text default null, p_payment_status text default null, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  o public.orders;
  updated public.orders;
begin
  perform public.assert_admin();
  select * into o from public.orders where reference = p_reference for update;
  if o is null then raise exception 'order_not_found'; end if;

  update public.orders
     set status = coalesce(p_status, status),
         payment_status = coalesce(p_payment_status, payment_status)
   where id = o.id
  returning * into updated;

  if updated.status <> o.status then
    insert into public.order_events (order_id, kind, from_value, to_value, actor) values (o.id, 'status', o.status, updated.status, auth.uid());
  end if;
  if updated.payment_status <> o.payment_status then
    insert into public.order_events (order_id, kind, from_value, to_value, actor) values (o.id, 'payment', o.payment_status, updated.payment_status, auth.uid());
  end if;
  if nullif(btrim(coalesce(p_note, '')), '') is not null then
    insert into public.order_events (order_id, kind, note, actor) values (o.id, 'note', left(btrim(p_note), 1000), auth.uid());
  end if;
  return public.order_json(updated, true);
end;
$$;

create or replace function public.admin_overview()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  threshold integer := (select low_stock_threshold from public.store_settings where id);
begin
  perform public.assert_admin();
  return jsonb_build_object(
    'currency', (select currency from public.store_settings where id),
    'checkoutEnabled', (select coalesce((checkout ->> 'enabled')::boolean, false) from public.store_settings where id),
    'revenue30', (select coalesce(sum(total), 0) from public.orders where status <> 'cancelled' and created_at > now() - interval '30 days'),
    'orders30', (select count(*) from public.orders where created_at > now() - interval '30 days'),
    'awaiting', (select count(*) from public.orders where status in ('pending', 'confirmed')),
    'unpaid', (select count(*) from public.orders where payment_status = 'unpaid' and status <> 'cancelled'),
    'recent', coalesce((select jsonb_agg(public.order_json(o, false) order by o.created_at desc) from (select * from public.orders order by created_at desc limit 6) o), '[]'::jsonb),
    'lowStock', coalesce((
      select jsonb_agg(jsonb_build_object('sku', v.sku, 'productId', p.id, 'product', p.name, 'colorway', c.name, 'size', v.size, 'stock', v.stock, 'status', p.status)
                       order by v.stock, p.name)
        from public.variants v
        join public.products p on p.id = v.product_id
        join public.colorways c on c.product_id = v.product_id and c.id = v.colorway_id
       where v.stock <= threshold and p.status <> 'archived'
    ), '[]'::jsonb),
    'products', jsonb_build_object(
      'active', (select count(*) from public.products where status = 'active'),
      'draft', (select count(*) from public.products where status = 'draft')
    )
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin functions are not callable by visitors at all.

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.assert_admin()', 'public.admin_catalog()', 'public.assert_publishable(text)',
    'public.admin_save_product(jsonb)', 'public.admin_set_product_status(text, text)', 'public.admin_delete_product(text)',
    'public.admin_set_rail(jsonb)', 'public.admin_set_featured(jsonb)', 'public.admin_save_collection(jsonb)',
    'public.admin_delete_collection(text)', 'public.admin_save_lookbook(jsonb)', 'public.admin_create_media(jsonb)',
    'public.admin_update_media(text, text, text)', 'public.admin_unused_media()', 'public.admin_delete_media(jsonb)',
    'public.admin_save_settings(jsonb, jsonb)', 'public.order_json(public.orders, boolean)',
    'public.admin_orders(text, text, integer, integer)', 'public.admin_order(text)',
    'public.admin_update_order(text, text, text, text)', 'public.admin_overview()'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;


-- ===== 20261028120500_api_grants.sql =====

-- STILLFORM · Data API permissions
--
-- The complete list of what the Data API roles may touch. Newer Supabase
-- projects can be created without automatically exposing new tables and
-- functions; older ones expose everything by default. This file first
-- removes whatever was granted, then grants exactly what the store needs,
-- so both kinds of project end up with the same, minimal permissions.
--
--   anon           visitors: read the published catalogue, place orders
--   authenticated  signed-in users: the same, plus the dashboard's tables and
--                  functions. Row level security and each admin function's
--                  own is_admin() check limit all of it to administrators.
--
-- Rows are still filtered by the policies in …_security.sql: a grant only
-- opens the door, row level security decides what is behind it.

grant usage on schema public to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Tables

revoke all on table
  public.media, public.categories, public.products, public.colorways, public.colorway_media, public.variants,
  public.collections, public.collection_products, public.rail_placements, public.featured_products,
  public.product_pairings, public.lookbooks, public.lookbook_spreads, public.looks, public.look_pieces,
  public.store_settings, public.store_private_settings, public.orders, public.order_items, public.order_events,
  public.admins
from anon, authenticated;

-- The published catalogue and public settings (policies show published rows only).
grant select on table
  public.media, public.categories, public.products, public.colorways, public.colorway_media, public.variants,
  public.collections, public.collection_products, public.rail_placements, public.featured_products,
  public.product_pairings, public.lookbooks, public.lookbook_spreads, public.looks, public.look_pieces,
  public.store_settings
to anon, authenticated;

-- Catalogue editing from the dashboard (policies: administrators only).
-- Categories are set up by the seed and not edited from the dashboard.
grant insert, update, delete on table
  public.media, public.products, public.colorways, public.colorway_media, public.variants,
  public.collections, public.collection_products, public.rail_placements, public.featured_products,
  public.product_pairings, public.lookbooks, public.lookbook_spreads, public.looks, public.look_pieces
to authenticated;
grant update on table public.store_settings to authenticated;

-- Administrator-only reads (policies: administrators only).
grant select, update on table public.store_private_settings to authenticated;
grant select on table public.orders, public.order_items, public.order_events to authenticated;

-- Orders are written only by place_order() and admin_update_order(), which
-- run as the owner. No API role may write them, or touch the admin list
-- (is_admin() reads it as the owner).
revoke all on sequence public.order_number_seq from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Functions

revoke all on function
  public.touch_updated_at(), public.orders_guard(),
  public.is_admin(), public.media_is_public(text), public.media_json(public.media), public.catalog_json(boolean),
  public.storefront_catalog(), public.place_order(jsonb),
  public.assert_admin(), public.assert_publishable(text), public.sku_for(text, text, text), public.order_json(public.orders, boolean),
  public.admin_catalog(), public.admin_save_product(jsonb), public.admin_set_product_status(text, text), public.admin_delete_product(text),
  public.admin_set_rail(jsonb), public.admin_set_featured(jsonb), public.admin_save_collection(jsonb), public.admin_delete_collection(text),
  public.admin_save_lookbook(jsonb), public.admin_create_media(jsonb), public.admin_update_media(text, text, text),
  public.admin_unused_media(), public.admin_delete_media(jsonb), public.admin_save_settings(jsonb, jsonb),
  public.admin_orders(text, text, integer, integer), public.admin_order(text),
  public.admin_update_order(text, text, text, text), public.admin_overview()
from public, anon, authenticated;

-- Storefront. place_order runs as the owner and validates and prices every
-- request itself; is_admin and media_is_public run as the owner to read the
-- admin list and publication state, and only ever return a yes or no.
grant execute on function
  public.storefront_catalog(), public.catalog_json(boolean), public.media_json(public.media),
  public.media_is_public(text), public.is_admin(), public.place_order(jsonb)
to anon, authenticated;

-- Dashboard. Every admin_* function starts with assert_admin(), which raises
-- not_authorized for anyone not listed in public.admins. admin_update_order
-- is the only one that runs as the owner. The helpers are called from inside
-- the admin functions.
grant execute on function
  public.assert_admin(), public.assert_publishable(text), public.sku_for(text, text, text), public.order_json(public.orders, boolean),
  public.admin_catalog(), public.admin_save_product(jsonb), public.admin_set_product_status(text, text), public.admin_delete_product(text),
  public.admin_set_rail(jsonb), public.admin_set_featured(jsonb), public.admin_save_collection(jsonb), public.admin_delete_collection(text),
  public.admin_save_lookbook(jsonb), public.admin_create_media(jsonb), public.admin_update_media(text, text, text),
  public.admin_unused_media(), public.admin_delete_media(jsonb), public.admin_save_settings(jsonb, jsonb),
  public.admin_orders(text, text, integer, integer), public.admin_order(text),
  public.admin_update_order(text, text, text, text), public.admin_overview()
to authenticated;

-- touch_updated_at and orders_guard are trigger functions: they run as part
-- of a table write and need no grant.


-- ===== 20261029120000_checkout_protection.sql =====

-- STILLFORM · Checkout protection
--
-- Orders no longer come straight from the browser. The place-order Edge
-- Function (supabase/functions/place-order) receives the checkout, checks
-- this throttle, verifies a Cloudflare Turnstile token with Cloudflare, and
-- only then calls place_order() with the server's own key. place_order()
-- itself is unchanged: it still validates, prices and reserves stock in one
-- transaction.
--
--   anon, authenticated   may no longer call place_order() at all, so the
--                         protection can't be skipped by calling the API
--   service_role          (the Edge Function) calls checkout_allow() and
--                         place_order()
--
-- Safe to run again.

-- ---------------------------------------------------------------------------
-- Attempts per connection, kept for a day. The function stores a keyed hash
-- of the visitor's IP address, never the address itself.

create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to service_role;

create table if not exists private.checkout_attempts (
  client text not null check (char_length(client) between 1 and 128),
  attempted_at timestamptz not null default now()
);
create index if not exists checkout_attempts_client_idx on private.checkout_attempts (client, attempted_at);
create index if not exists checkout_attempts_time_idx on private.checkout_attempts (attempted_at);
alter table private.checkout_attempts enable row level security;
revoke all on table private.checkout_attempts from public, anon, authenticated;
grant select, insert, delete on table private.checkout_attempts to service_role;

-- Records an attempt and says whether it may go ahead: at most 5 attempts in
-- 10 minutes and 20 in a day from one connection. Failed attempts count too.
create or replace function public.checkout_allow(p_client text)
returns boolean
language plpgsql
volatile
set search_path = ''
as $$
declare
  recent integer;
  today integer;
begin
  if p_client is null or char_length(p_client) not between 1 and 128 then
    raise exception 'invalid_client';
  end if;
  -- One decision at a time per connection, so parallel requests can't slip through together.
  perform pg_advisory_xact_lock(hashtext('stillform.checkout:' || p_client));
  delete from private.checkout_attempts where attempted_at < now() - interval '1 day';
  select count(*) filter (where attempted_at > now() - interval '10 minutes'), count(*)
    into recent, today
    from private.checkout_attempts
   where client = p_client;
  if recent >= 5 or today >= 20 then
    return false;
  end if;
  insert into private.checkout_attempts (client) values (p_client);
  return true;
end;
$$;

-- ---------------------------------------------------------------------------
-- Who may call what

grant usage on schema public to service_role;

revoke all on function public.checkout_allow(text) from public, anon, authenticated;
grant execute on function public.checkout_allow(text) to service_role;

revoke all on function public.place_order(jsonb) from public, anon, authenticated;
grant execute on function public.place_order(jsonb) to service_role;


