    ('editorial/detail-oxford', '/media/editorial/detail-oxford-2048.webp', 'The soft, unlined button-down collar of the pale blue Oxford Shirt', 2048, 2048, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/detail-oxford-640.webp"},{"width":1080,"src":"/media/editorial/detail-oxford-1080.webp"},{"width":1600,"src":"/media/editorial/detail-oxford-1600.webp"},{"width":2048,"src":"/media/editorial/detail-oxford-2048.webp"}]'::jsonb, null),
    ('editorial/look-black-tee', '/media/editorial/look-black-tee-1856.webp', 'A man in the black Heavyweight Tee against a graphite backdrop, side-lit', 1856, 2304, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-black-tee-640.webp"},{"width":1080,"src":"/media/editorial/look-black-tee-1080.webp"},{"width":1600,"src":"/media/editorial/look-black-tee-1600.webp"},{"width":1856,"src":"/media/editorial/look-black-tee-1856.webp"}]'::jsonb, '50% 30%'),
    ('editorial/look-moss-rust', '/media/editorial/look-moss-rust-2048.webp', 'A model in the Lambswool Cardigan in moss, worn open over the rust Long-Sleeve Henley, in a plaster-walled studio beside a clothing rail', 2048, 1143, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-moss-rust-640.webp"},{"width":1080,"src":"/media/editorial/look-moss-rust-1080.webp"},{"width":1600,"src":"/media/editorial/look-moss-rust-1600.webp"},{"width":2048,"src":"/media/editorial/look-moss-rust-2048.webp"}]'::jsonb, '20% 50%'),
    ('editorial/look-oxford-hoodie', '/media/editorial/look-oxford-hoodie-2048.webp', 'A man seated on a wooden bench in the grey marl Fleece Hoodie over the pale blue Oxford Shirt, in a bare, sunlit room', 2048, 1374, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-oxford-hoodie-640.webp"},{"width":1080,"src":"/media/editorial/look-oxford-hoodie-1080.webp"},{"width":1600,"src":"/media/editorial/look-oxford-hoodie-1600.webp"},{"width":2048,"src":"/media/editorial/look-oxford-hoodie-2048.webp"}]'::jsonb, '80% 60%'),
    ('editorial/look-stripe-oat', '/media/editorial/look-stripe-oat-1856.webp', 'A model in the Mariner Long Sleeve with the Fleece Crew in oat knotted over her shoulders, against a limestone wall', 1856, 2304, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-stripe-oat-640.webp"},{"width":1080,"src":"/media/editorial/look-stripe-oat-1080.webp"},{"width":1600,"src":"/media/editorial/look-stripe-oat-1600.webp"},{"width":1856,"src":"/media/editorial/look-stripe-oat-1856.webp"}]'::jsonb, '38% 40%')
