  insert into public.lookbook_spreads (id, lookbook_id, layout, note, position) values
    ('opening', 'lookbook-01', 'cinematic', null, 0),
    ('foundation', 'lookbook-01', 'pair', 'The Heavyweight Tee is the piece the rest of the collection is built on: 240 gsm jersey, dense enough to hold its line, in black and in bone.', 1),
